def main():
    T = input().strip()
    N = int(input().strip())
    S = []
    for _ in range(N):
        tmp = input().strip().split()
        del(tmp[0])
        S.append(tmp)

    INF = 10**18
    dp = [[INF] * (len(T) + 1) for _ in range(N + 1)]
    dp[0][0] = 0

    for i in range(1, N + 1):
        for j in range(len(T) + 1):
            dp[i][j] = dp[i - 1][j]

        for s in S[i - 1]:
            for j in range(len(T) + 1):
                post_len = j + len(s)
                if post_len > len(T):
                    continue

                if T[j:post_len] == s:
                    dp[i][post_len] = min(dp[i][post_len], dp[i - 1][j] + 1)

    if dp[N][len(T)] == INF:
        print(-1)
    else:
        print(dp[N][len(T)])

    return
